// Build summarization prompt: cap at 2000 tokens (~1500 words)
const clusterItems = $input.all();
const excerpts = clusterItems
  .map(item => `${item.json.title}\n${(item.json.excerpt || item.json.full_text || '').slice(0, 400)}`)
  .join('\n---\n');
const source_excerpts = excerpts.slice(0, 3000); // Hard cap

const cluster = $('Get Cluster ID').first().json;
const canonicalTitle = clusterItems[0]?.json?.title || 'Unknown';
const itemCount = clusterItems.length;
const priorityScore = cluster.priority_score || 0;

// Select model based on priority (locked decision from plan)
const model = priorityScore >= 90 ? 'claude-opus-4-7' : 'claude-sonnet-4-6';

const systemPrompt = `You are an AI news analyst for NeuralForge. You write summaries at three reading levels simultaneously.\n\nRules:\n- beginner: ~200 words, zero jargon, plain English, start with "What happened:", explain why non-technical people should care\n- intermediate: ~100 words, for working developers, include specific model names, benchmark numbers, API changes if relevant\n- expert: ~50 words, for ML engineers and researchers, dense, technical terms permitted, focus on architecture/methodology/implication\n- Never pad to hit word counts — say less if there is less to say\n- Output valid JSON only, no text outside the JSON object`;

const userPrompt = `Story cluster: ${canonicalTitle}\nSources (${itemCount} sources corroborate this story):\n${source_excerpts}\n\nOutput this exact JSON:\n{\n  "beginner": "<~200 words. Plain English. Start with 'What happened:'. Why should non-technical readers care.>",\n  "intermediate": "<~100 words. For working developers. Include model names, benchmark numbers, API changes.>",\n  "expert": "<~50 words. For ML engineers. Dense. Technical terms. Architecture/training methodology/implication.>",\n  "category": "<confirm: model_release|tool_launch|research_paper|funding|opinion|tutorial|security|regulation>",\n  "headline_score_boost": <-10 to +10 integer>\n}`;

return [{ json: {
  cluster_id: cluster.cluster_id,
  priority_score: priorityScore,
  model,
  system_prompt: systemPrompt,
  user_prompt: userPrompt,
  item_id: $('Webhook Trigger').first().json.body.item_id
}}];

const response = $input.first().json;
const context = $('Build Summarization Prompt').first().json;
const text = response.content?.[0]?.text || '{}';

let parsed;
try { parsed = JSON.parse(text); } catch { parsed = {}; }

const inputTokens = response.usage?.input_tokens || 0;
const outputTokens = response.usage?.output_tokens || 0;

// Cost calculation based on model
const isOpus = context.model.includes('opus');
const priceInput = isOpus ? 0.000015 : 0.000003;
const priceOutput = isOpus ? 0.000075 : 0.000015;
const costUsd = inputTokens * priceInput + outputTokens * priceOutput;

return [{ json: {
  cluster_id: context.cluster_id,
  item_id: context.item_id,
  priority_score: context.priority_score,
  model: context.model,
  summary_beginner: parsed.beginner || null,
  summary_intermediate: parsed.intermediate || null,
  summary_expert: parsed.expert || null,
  category: parsed.category || null,
  headline_score_boost: parsed.headline_score_boost || 0,
  input_tokens: inputTokens,
  output_tokens: outputTokens,
  cost_usd: costUsd
}}];
